// Package workload implements self-measuring CPU-bound borrower and victim jobs.
package workload

import (
	"context"
	"errors"
	"fmt"
	"runtime"
	runtimemetrics "runtime/metrics"
	"sync"
	"sync/atomic"
	"time"

	"cpu-scheduler-eval/internal/metrics"
)

var sink atomic.Uint64

// Config sets the periodic CPU work generated by one container process.
type Config struct {
	Role       string        `json:"role"`
	Duration   time.Duration `json:"duration"`
	Period     time.Duration `json:"period"`
	CPUTime    time.Duration `json:"cpu_time"`
	Workers    int           `json:"workers"`
	GOMAXPROCS int           `json:"gomaxprocs"`
}

// Result contains app response latency plus Go runtime scheduler latency.
type Result struct {
	Role                string          `json:"role"`
	Operations          int             `json:"operations"`
	MissedReleases      int             `json:"missed_releases"`
	ThroughputOpsPerSec float64         `json:"throughput_ops_per_sec"`
	ApplicationLatency  metrics.Summary `json:"application_latency"`
	GoSchedulerLatency  metrics.Summary `json:"go_scheduler_latency"`
	GoSchedulerMethod   string          `json:"go_scheduler_method"`
	EffectiveGOMAXPROCS int             `json:"effective_gomaxprocs"`
	ElapsedNanoseconds  int64           `json:"elapsed_ns"`
}

// Run executes Config.Workers periodic CPU jobs and returns process-local
// measurements. Application latency is release-to-completion response time.
func Run(ctx context.Context, config Config) (Result, error) {
	if config.Role != "borrower" && config.Role != "victim" {
		return Result{}, fmt.Errorf("role must be borrower or victim, got %q", config.Role)
	}
	if config.Duration <= 0 || config.Period <= 0 || config.CPUTime <= 0 || config.Workers <= 0 {
		return Result{}, errors.New("duration, period, CPU time, and workers must be positive")
	}
	if config.CPUTime > config.Duration {
		return Result{}, errors.New("CPU time must not exceed duration")
	}

	if config.GOMAXPROCS > 0 {
		previous := runtime.GOMAXPROCS(config.GOMAXPROCS)
		defer runtime.GOMAXPROCS(previous)
	}
	effectiveProcs := runtime.GOMAXPROCS(0)
	before, err := readSchedHistogram()
	if err != nil {
		return Result{}, err
	}

	start := time.Now()
	end := start.Add(config.Duration)
	workerResults := make([]workerResult, config.Workers)
	var workers sync.WaitGroup
	workers.Add(config.Workers)
	for i := range workerResults {
		go func(index int) {
			defer workers.Done()
			workerResults[index] = runWorker(ctx, start, end, config.Period, config.CPUTime, config.Role)
		}(i)
	}
	workers.Wait()
	elapsed := time.Since(start)

	var samples []float64
	operations, missed := 0, 0
	for _, result := range workerResults {
		if result.err != nil {
			return Result{}, result.err
		}
		samples = append(samples, result.latencyNS...)
		operations += result.operations
		missed += result.missed
	}

	after, err := readSchedHistogram()
	if err != nil {
		return Result{}, err
	}
	delta, ok := histogramDelta(before, after)
	if !ok {
		return Result{}, errors.New("Go runtime scheduler histogram changed shape during run")
	}

	return Result{
		Role:                config.Role,
		Operations:          operations,
		MissedReleases:      missed,
		ThroughputOpsPerSec: float64(operations) / elapsed.Seconds(),
		ApplicationLatency:  metrics.Summarize(samples),
		GoSchedulerLatency:  metrics.SummarizeRuntimeHistogram(delta),
		GoSchedulerMethod:   "runtime/metrics /sched/latencies:seconds; bucket-midpoint estimate, cumulative histogram delta",
		EffectiveGOMAXPROCS: effectiveProcs,
		ElapsedNanoseconds:  elapsed.Nanoseconds(),
	}, nil
}

type workerResult struct {
	latencyNS  []float64
	operations int
	missed     int
	err        error
}

func runWorker(ctx context.Context, start, end time.Time, period, cpuTime time.Duration, role string) workerResult {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	result := workerResult{}
	if err := setThreadComm(role); err != nil {
		result.err = fmt.Errorf("set workload thread name: %w", err)
		return result
	}
	release := start
	for release.Before(end) {
		if delay := time.Until(release); delay > 0 {
			timer := time.NewTimer(delay)
			select {
			case <-ctx.Done():
				timer.Stop()
				return result
			case <-timer.C:
			}
		}
		if ctx.Err() != nil {
			return result
		}

		if time.Until(end) <= 0 {
			return result
		}
		value, err := busyCPUFor(cpuTime)
		if err != nil {
			result.err = fmt.Errorf("measure thread CPU work: %w", err)
			return result
		}
		done := time.Now()
		sink.Store(value)
		result.latencyNS = append(result.latencyNS, float64(done.Sub(release).Nanoseconds()))
		result.operations++

		release = release.Add(period)
		if !release.After(done) {
			skipped := int(done.Sub(release)/period) + 1
			result.missed += skipped
			release = release.Add(time.Duration(skipped) * period)
		}
	}
	return result
}

func readSchedHistogram() (*runtimemetrics.Float64Histogram, error) {
	sample := []runtimemetrics.Sample{{Name: "/sched/latencies:seconds"}}
	runtimemetrics.Read(sample)
	if sample[0].Value.Kind() != runtimemetrics.KindFloat64Histogram {
		return nil, errors.New("Go runtime does not expose /sched/latencies:seconds")
	}
	hist := sample[0].Value.Float64Histogram()
	return &runtimemetrics.Float64Histogram{
		Buckets: append([]float64(nil), hist.Buckets...),
		Counts:  append([]uint64(nil), hist.Counts...),
	}, nil
}

func histogramDelta(before, after *runtimemetrics.Float64Histogram) (*runtimemetrics.Float64Histogram, bool) {
	if before == nil || after == nil || len(before.Buckets) != len(after.Buckets) || len(before.Counts) != len(after.Counts) {
		return nil, false
	}
	for i := range before.Buckets {
		if before.Buckets[i] != after.Buckets[i] {
			return nil, false
		}
	}
	for i := range before.Counts {
		if after.Counts[i] < before.Counts[i] {
			return nil, false
		}
	}
	delta := &runtimemetrics.Float64Histogram{
		Buckets: append([]float64(nil), after.Buckets...),
		Counts:  make([]uint64, len(after.Counts)),
	}
	for i := range delta.Counts {
		delta.Counts[i] = after.Counts[i] - before.Counts[i]
	}
	return delta, true
}
